+#!/usr/bin/env node
+// Generates site/src/lab/protocol.ts from spec/lab-protocol-schema.json.
+// No hand-written .d.ts (docs/playground-spec.md §5.1's round-2 debate
+// guardrail) — this is the one place LabRequest/LabResponse's TS shape is
+// allowed to exist; everything else imports from the generated file.
+// Same "generate, commit, CI diffs" pattern as spec/cst-schema.json /
+// spec/ir-schema.json: run this script, commit the output, and a CI step
+// re-runs it and diffs to catch drift instead of letting the hand-authored
+// schema and the generated types silently disagree.
+//
+// Usage: npm run gen:lab-types (from site/)
+
+import { compile } from "json-schema-to-typescript";
+import { readFile, writeFile, mkdir } from "node:fs/promises";
+import { fileURLToPath } from "node:url";
+import path from "node:path";
+
+const siteDir = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
+const schemaPath = path.join(siteDir, "..", "spec", "lab-protocol-schema.json");
+const outPath = path.join(siteDir, "src", "lab", "protocol.ts");
+
+const schema = JSON.parse(await readFile(schemaPath, "utf-8"));
+
+// Only the two independent roots — NOT every titled $defs entry.
+// json-schema-to-typescript's `compile()` bundles every type a root
+// transitively references into that same call's output, so compiling each
+// titled def separately would redeclare shared dependencies (ParseResult,
+// LabToken, CstNode, ...) once per caller, a TypeScript duplicate-identifier
+// error. labRequest's only dependency (Method) and labResponse's dependency
+// tree (ParseResult, LabToken, CstNode, CstBranch, CstToken) don't overlap,
+// so these two calls together emit every type in the schema exactly once.
+const defNames = ["labRequest", "labResponse"];
+
+const banner = `/* eslint-disable */
+/**
+ * This file was automatically generated by site/scripts/gen-lab-types.mjs
+ * from spec/lab-protocol-schema.json. Do not edit by hand — run
+ * \`npm run gen:lab-types\` (from site/) instead.
+ */
+
+`;
+
+const parts = [];
+for (const name of defNames) {
+  // Compile targets a single schema-as-root; splice the chosen $defs entry
+  // in as the root while keeping the full $defs map alongside it, so any
+  // "#/$defs/..." $ref inside still resolves.
+  const rootSchema = { ...schema.$defs[name], $defs: schema.$defs };
+  const ts = await compile(rootSchema, name, {
+    cwd: path.dirname(schemaPath),
+    bannerComment: "",
+    additionalProperties: false,
+    unreachableDefinitions: false,
+  });
+  parts.push(ts.trim());
+}
+
+await mkdir(path.dirname(outPath), { recursive: true });
+await writeFile(outPath, banner + parts.join("\n\n") + "\n");
+console.log(`wrote ${path.relative(siteDir, outPath)}`);

