+/* eslint-disable */
+/**
+ * This file was automatically generated by site/scripts/gen-lab-types.mjs
+ * from spec/lab-protocol-schema.json. Do not edit by hand — run
+ * `npm run gen:lab-types` (from site/) instead.
+ */
+
+/**
+ * Which table-construction method to build with — mirrors gramaire.Method exactly.
+ */
+export type Method = "Canonical" | "LALR" | "IELR";
+
+/**
+ * A request from the Lab UI: the full .gram.md source, an optional target-language input to parse, and the table-construction method to build with. Omitting `input` (or sending null) means compile-only.
+ */
+export interface LabRequest {
+  source: string;
+  input?: string | null;
+  method: Method;
+}
+
+/**
+ * The same node shape as cst-schema.json's $defs/node (Cst.toJson emits it identically here, just embedded as ParseResult.cst instead of wrapped in the {cstVersion, root} envelope that artifact's own top level adds) — kept in sync by hand, both schemas are hand-authored from the same Cst.scala encoder.
+ */
+export type CstNode = CstBranch | CstToken;
+
+/**
+ * The Lab's full response: whether the grammar itself built, any diagnostics, and — if input was given and the grammar built — the parse result.
+ */
+export interface LabResponse {
+  labProtocolVersion: number;
+  /**
+   * True iff the grammar compiled and its tables built with no unresolved conflicts. When false, `diagnostics` names why and `parse` is always null.
+   */
+  buildOk: boolean;
+  /**
+   * Rendered conflict/undefined-nonterminal messages (Diagnostics.renderConflicts), or a single grammar-notation parse error, when buildOk is false. Empty when buildOk is true.
+   */
+  diagnostics: string[];
+  /**
+   * Present only when the request carried `input` and the grammar built successfully; null otherwise (compile-only requests, or any build failure).
+   */
+  parse: ParseResult | null;
+}
+/**
+ * The outcome of parsing LabRequest.input against the compiled grammar. `tokens` is populated even on a reject, so the Tokens tab still has something to show; `cst` is null unless `accepted`.
+ */
+export interface ParseResult {
+  accepted: boolean;
+  /**
+   * The reject reason (a lexical-error notice, or ParseError.render) when accepted is false; null when accepted.
+   */
+  message: string | null;
+  tokens: LabToken[];
+  cst: CstNode | null;
+}
+/**
+ * A single lexed token from the Lab's Tokens tab, with its source span (start/end are code-unit offsets into LabRequest.input, [start, end) — matching gramaire.Spanned's own convention).
+ */
+export interface LabToken {
+  text: string;
+  terminal: string;
+  start: number;
+  end: number;
+}
+export interface CstBranch {
+  rule: number;
+  children: CstNode[];
+}
+export interface CstToken {
+  token: string;
+  text: string;
+}

